      if (chunk.IsEmpty()) {
        return isolate::ThrowException(
            String::NewFromUtf8(isolate, "Failed to create string from stdout data", NewStringType::kNormal)
                .ToLocalChecked());
      }
      if (accumulator.IsEmpty()) {
        accumulator = chunk;
      } else {
        accumulator = String::Concatenate(accumulator, chunk);
      }
