// versions post docusaurus
const versions = require(`${CWD}/versions.json`);
// versions pre docusaurus
const oldversions = require(`${CWD}/oldversions.json`);

function Versions(props) {
    const latestStableVersion = versions[0];
    const repoUrl = `https://github.com/${siteConfig.organizationName}/${
      siteConfig.projectName

raw_output:
}`;
    const versionsList = [
        ...versions,
        ...oldversions,
    ];
    const versionsListWithNumbers = versionsList.map((version) => {
        const versionNumber = version.version;
        return {
            ...version,
            versionNumber,
        };
    });
    const versionsListSorted = versionsListWithNumbers.sort((a, b) => {
        const aParts = a.versionNumber.split('.');
        const bParts = b.versionNumber.split('.');
        for (let i = 0; i < Math.min(aParts.length, bParts.length); i++) {
            const aNum = parseInt(aParts[i], 10);
            const bNum = parseInt(bParts[i], 10);
            if (aNum !== bNum) {
                return aNum - bNum;
            }
        }
        return aParts.length - bParts.length;
    });
    const versionsListSortedUnique = [...new Set(versionsListSorted)];

    return (
        <div className="versions-container">
            <h2>Version Information</h2>
            <div className="versions-grid">
